serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: { "Access-Control-Allow-Origin": "*", "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type" } });
  }
    const _denied = await requireAdmin(req);
    if (_denied) return _denied;
  try {
    const supabase = createClient(Deno.env.get("SUPABASE_URL") ?? "", Deno.env.get("SUPABASE_SERVICE_ROLE_KEY") ?? "");
    const courseId = "33333333-4444-5555-6666-777777777777";
    const { data: existing } = await supabase.from("chapters").select("id").eq("course_id", courseId);
    if (existing && existing.length > 0) await supabase.from("chapters").delete().eq("course_id", courseId);
    await supabase.from("courses").delete().eq("id", courseId);
    const { data: course, error: courseError } = await supabase.from("courses").insert({ id: courseId, title: courseData.title, description: courseData.description, is_published: true }).select().single();
    if (courseError) throw courseError;
    for (const mod of courseData.modules) {
      const { data: chapter, error: chErr } = await supabase.from("chapters").insert({ course_id: course.id, title: mod.title, description: mod.description, order_index: mod.order_index }).select().single();
      if (chErr) throw chErr;
      for (const lesson of mod.lessons) {
        const { data: video, error: vErr } = await supabase.from("videos").insert({ chapter_id: chapter.id, title: lesson.title, description: lesson.description, order_index: lesson.order_index }).select().single();
        if (vErr) throw vErr;
        const { data: quiz, error: qErr } = await supabase.from("quizzes").insert({ video_id: video.id, chapter_id: chapter.id, quiz_type: "mini_video", passing_score: 80 }).select().single();
        if (qErr) throw qErr;
        for (let i = 0; i < lesson.questions.length; i++) {
          const q = lesson.questions[i];
          await supabase.from("quiz_questions").insert({ quiz_id: quiz.id, question_text: q.q, options: q.opts, correct_answer_index: q.a, explanation: q.exp, order_index: i });
        }
        const { data: chapterQuiz, error: cqErr } = await supabase.from("quizzes").insert({ chapter_id: chapter.id, quiz_type: "chapter_end", passing_score: 80 }).select().single();
        if (cqErr) throw cqErr;
        for (let i = 0; i < lesson.questions.length; i++) {
          const q = lesson.questions[i];
          await supabase.from("quiz_questions").insert({ quiz_id: chapterQuiz.id, question_text: q.q, options: q.opts, correct_answer_index: q.a, explanation: q.exp, order_index: i });
        }
      }
    }
    return new Response(JSON.stringify({ success: true, message: "DevOps & Cloud Engineering course seeded", courseId }), { headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" } });
  } catch (error) {
    return new Response(JSON.stringify({ error: error.message }), { status: 500, headers: { "Content-Type": "application/json", "Access-Control-Allow-Origin": "*" } });
  }
});
